"use client";

import { DialogTitle } from "@radix-ui/react-dialog";
import {
  ChevronRightIcon,
  ClockIcon,
  FileTextIcon,
  MagnifyingGlassIcon,
} from "@radix-ui/react-icons";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useRef, useState } from "react";
import { Badge } from "@/components/ui/badge";
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Input } from "@/components/ui/input";
import { routes } from "@/config/routes";
import { type DocSearchResult, useDocsSearch } from "@/hooks/use-docs-search";
import { cn } from "@/lib/utils";

// Popular docs for initial suggestions
const POPULAR_DOCS = [
  {
    title: "Introduction",
    url: `${routes.docs}/introduction`,
    description: "Get started with Shipkit",
  },
  {
    title: "Quickstart Guide",
    url: `${routes.docs}/quickstart`,
    description: "Quick setup and deployment",
  },
  {
    title: "Authentication",
    url: `${routes.docs}/auth`,
    description: "User authentication and authorization",
  },
  {
    title: "Database",
    url: `${routes.docs}/database`,
    description: "Database setup and configuration",
  },
  {
    title: "Deployment",
    url: `${routes.docs}/deployment`,
    description: "Deploy your application",
  },
];

// Recent searches storage key
const RECENT_SEARCHES_KEY = "docs-recent-searches";
const MAX_RECENT_SEARCHES = 5;

export function DocsSearch() {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [recentSearches, setRecentSearches] = useState<string[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  const { query, setQuery, results, isLoading, error, search, clearResults, hasSearched } =
    useDocsSearch({
      debounceDelay: 300,
      minQueryLength: 1,
      limit: 8,
    });

  // Load recent searches from localStorage
  useEffect(() => {
    try {
      const stored = localStorage.getItem(RECENT_SEARCHES_KEY);
      if (stored) {
        // eslint-disable-next-line react-hooks/set-state-in-effect -- syncing with external localStorage on mount
        setRecentSearches(JSON.parse(stored));
      }
    } catch (error) {
      console.warn("Failed to load recent searches:", error);
    }
  }, []);

  // Save search to recent searches
  const saveToRecentSearches = useCallback((searchQuery: string) => {
    if (!searchQuery.trim()) return;

    try {
      setRecentSearches((prev) => {
        const updated = [searchQuery, ...prev.filter((s) => s !== searchQuery)].slice(
          0,
          MAX_RECENT_SEARCHES
        );
        localStorage.setItem(RECENT_SEARCHES_KEY, JSON.stringify(updated));
        return updated;
      });
    } catch (error) {
      console.warn("Failed to save recent search:", error);
    }
  }, []);

  // Get current items for display (results, popular docs, or recent searches)
  const currentItems = hasSearched ? results : [];
  const showPopularDocs = !hasSearched && !query.trim();
  const showRecentSearches = !hasSearched && query.trim() && recentSearches.length > 0;

  // Calculate total items for keyboard navigation
  const totalItems =
    currentItems.length +
    (showPopularDocs ? POPULAR_DOCS.length : 0) +
    (showRecentSearches ? recentSearches.length : 0);

  // Reset selection when items change
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- resets selection when search results change
    setSelectedIndex(0);
  }, [totalItems, query]);

  // Handle command execution
  const runCommand = useCallback((command: () => unknown) => {
    setOpen(false);
    command();
  }, []);

  // Handle search result navigation
  const handleResultSelect = useCallback(
    (result: DocSearchResult) => {
      saveToRecentSearches(query);
      runCommand(() => router.push(result.url));
    },
    [query, saveToRecentSearches, runCommand, router]
  );

  // Handle popular doc navigation
  const handlePopularDocSelect = useCallback(
    (doc: (typeof POPULAR_DOCS)[0]) => {
      runCommand(() => router.push(doc.url));
    },
    [runCommand, router]
  );

  // Handle recent search selection
  const handleRecentSearchSelect = useCallback(
    (recentQuery: string) => {
      setQuery(recentQuery);
      void search(recentQuery);
    },
    [setQuery, search]
  );

  // Keyboard navigation
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (!open) return;

      switch (e.key) {
        case "ArrowDown":
          e.preventDefault();
          setSelectedIndex((prev) => (prev + 1) % Math.max(1, totalItems));
          break;
        case "ArrowUp":
          e.preventDefault();
          setSelectedIndex((prev) => (prev === 0 ? totalItems - 1 : prev - 1));
          break;
        case "Enter": {
          e.preventDefault();
          if (totalItems === 0) return;

          // Determine which item is selected
          let currentIndex = 0;

          // Check search results
          if (selectedIndex < currentItems.length && currentItems[selectedIndex]) {
            handleResultSelect(currentItems[selectedIndex]);
            return;
          }
          currentIndex += currentItems.length;

          // Check popular docs
          if (showPopularDocs && selectedIndex < currentIndex + POPULAR_DOCS.length) {
            const docIndex = selectedIndex - currentIndex;
            if (POPULAR_DOCS[docIndex]) {
              handlePopularDocSelect(POPULAR_DOCS[docIndex]);
              return;
            }
          }
          currentIndex += showPopularDocs ? POPULAR_DOCS.length : 0;

          // Check recent searches
          if (showRecentSearches && selectedIndex < currentIndex + recentSearches.length) {
            const recentIndex = selectedIndex - currentIndex;
            if (recentSearches[recentIndex]) {
              handleRecentSearchSelect(recentSearches[recentIndex]);
              return;
            }
          }
          break;
        }
        case "Escape":
          setOpen(false);
          break;
      }
    },
    [
      open,
      totalItems,
      selectedIndex,
      currentItems,
      showPopularDocs,
      showRecentSearches,
      recentSearches,
      handleResultSelect,
      handlePopularDocSelect,
      handleRecentSearchSelect,
    ]
  );

  // Handle dialog open/close
  const handleOpenChange = useCallback(
    (newOpen: boolean) => {
      setOpen(newOpen);
      if (!newOpen) {
        clearResults();
        setSelectedIndex(0);
      } else {
        // Focus input when dialog opens
        setTimeout(() => inputRef.current?.focus(), 0);
      }
    },
    [clearResults]
  );

  // Render search result item
  const renderSearchResult = (result: DocSearchResult, index: number) => {
    const isSelected = selectedIndex === index;

    return (
      <CommandItem
        key={`result-${index}`}
        value={`result-${result.title}-${index}`}
        onSelect={() => handleResultSelect(result)}
        className={cn("flex cursor-pointer items-start gap-3 p-3", isSelected && "bg-accent")}
      >
        <FileTextIcon className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <span className="truncate text-sm font-medium">{result.title}</span>
            {result.section && (
              <Badge variant="outline" className="text-xs">
                {result.section}
              </Badge>
            )}
          </div>
          <p className="mt-1 line-clamp-2 text-xs text-muted-foreground">{result.content}</p>
        </div>
        <ChevronRightIcon className="h-3 w-3 shrink-0 text-muted-foreground" />
      </CommandItem>
    );
  };

  // Render popular doc item
  const renderPopularDoc = (doc: (typeof POPULAR_DOCS)[0], index: number) => {
    const isSelected = selectedIndex === currentItems.length + index;

    return (
      <CommandItem
        key={`popular-${index}`}
        value={`popular-${doc.title}-${index}`}
        onSelect={() => handlePopularDocSelect(doc)}
        className={cn("flex cursor-pointer items-center gap-3 p-3", isSelected && "bg-accent")}
      >
        <FileTextIcon className="h-4 w-4 text-muted-foreground" />
        <div className="flex-1">
          <span className="text-sm font-medium">{doc.title}</span>
          <p className="text-xs text-muted-foreground">{doc.description}</p>
        </div>
      </CommandItem>
    );
  };

  // Render recent search item
  const renderRecentSearch = (recentQuery: string, index: number) => {
    const isSelected = selectedIndex === currentItems.length + index;

    return (
      <CommandItem
        key={`recent-${index}`}
        value={`recent-${recentQuery}-${index}`}
        onSelect={() => handleRecentSearchSelect(recentQuery)}
        className={cn("flex cursor-pointer items-center gap-3 p-3", isSelected && "bg-accent")}
      >
        <ClockIcon className="h-4 w-4 text-muted-foreground" />
        <span className="text-sm">{recentQuery}</span>
      </CommandItem>
    );
  };

  return (
    <>
      <div className="relative w-full">
        <MagnifyingGlassIcon className="absolute left-2 top-3 h-4 w-4 text-muted-foreground" />
        <Input
          className="h-9 w-full rounded-[0.5rem] bg-background pl-8 text-sm text-muted-foreground"
          placeholder="Search docs..."
          onClick={() => setOpen(true)}
          readOnly
        />
      </div>

      <CommandDialog open={open} onOpenChange={handleOpenChange}>
        <div className="flex h-[300px] w-full flex-col">
          <DialogTitle className="sr-only">Search Documentation</DialogTitle>
          <CommandInput
            ref={inputRef}
            placeholder="Type to search documentation..."
            value={query}
            onValueChange={setQuery}
            onKeyDown={handleKeyDown}
          />
          <CommandList className="flex-1 overflow-y-auto">
            {isLoading && (
              <div className="p-4 text-center text-sm text-muted-foreground">Searching...</div>
            )}

            {error && (
              <div className="p-4 text-center">
                <p className="text-sm text-destructive">{error}</p>
              </div>
            )}

            {!isLoading && !error && hasSearched && results.length === 0 && (
              <CommandEmpty>No results found for &quot;{query}&quot;</CommandEmpty>
            )}

            {/* Search Results */}
            {!isLoading && results.length > 0 && (
              <CommandGroup heading="Documentation">
                {results.map((result, index) => renderSearchResult(result, index))}
              </CommandGroup>
            )}

            {/* Popular Documentation */}
            {!isLoading && showPopularDocs && (
              <CommandGroup heading="Popular Documentation">
                {POPULAR_DOCS.map((doc, index) => renderPopularDoc(doc, index))}
              </CommandGroup>
            )}

            {/* Recent Searches */}
            {!isLoading && showRecentSearches && (
              <CommandGroup heading="Recent Searches">
                {recentSearches.map((recentQuery, index) => renderRecentSearch(recentQuery, index))}
              </CommandGroup>
            )}
          </CommandList>
        </div>
      </CommandDialog>
    </>
  );
}

import type { Node } from "fumadocs-core/page-tree";
import { loader } from "fumadocs-core/source";
import { docs } from "@/.source/server";

/*
 * Documentation content source.
 *
 * Content lives in /docs as MDX and is compiled by fumadocs-mdx (see
 * source.config.ts). This module is the single entry point the /docs route,
 * sidebar, and search API read from.
 *
 * Only the *headless* half of fumadocs is used — `fumadocs-core` for the page
 * tree, slugs, and search index. Rendering stays on Shipkit's own components
 * because `fumadocs-ui` requires Tailwind v4 and Shipkit is on v3.
 */
export const source = loader({
  baseUrl: "/docs",
  source: docs.toFumadocsSource(),
});

export type DocPage = NonNullable<ReturnType<typeof source.getPage>>;

export interface NavItem {
  title: string;
  href: string;
  external?: boolean;
  description?: string;
}

export interface NavSection {
  title: string;
  items: NavItem[];
}

/** Section that collects top-level pages that aren't inside a folder. */
const ROOT_SECTION_TITLE = "Overview";

/** Page tree names are ReactNode; in practice fumadocs emits plain strings. */
function nodeName(name: unknown): string {
  if (typeof name === "string") return name;
  if (typeof name === "number") return String(name);
  return "";
}

/*
 * Flatten a page-tree branch into links.
 *
 * The docs sidebar renders a fixed two-level accordion (section -> links), so
 * folders nested deeper than one level are flattened into their parent section
 * rather than dropped.
 */
function collectPages(nodes: Node[]): NavItem[] {
  const items: NavItem[] = [];

  for (const node of nodes) {
    if (node.type === "page") {
      items.push({
        title: nodeName(node.name),
        href: node.url,
        ...(node.external === undefined ? {} : { external: node.external }),
      });
      continue;
    }

    if (node.type === "folder") {
      if (node.index) {
        items.push({ title: nodeName(node.index.name), href: node.index.url });
      }
      items.push(...collectPages(node.children));
    }
  }

  return items;
}

/** Sidebar navigation derived from the fumadocs page tree. */
export function getDocsNavigation(): NavSection[] {
  const tree = source.pageTree;
  const sections: NavSection[] = [];
  const rootItems: NavItem[] = [];

  for (const node of tree.children) {
    if (node.type === "folder") {
      sections.push({ title: nodeName(node.name), items: collectPages([node]) });
    } else if (node.type === "page") {
      rootItems.push({ title: nodeName(node.name), href: node.url });
    }
  }

  if (rootItems.length > 0) {
    sections.unshift({ title: ROOT_SECTION_TITLE, items: rootItems });
  }

  return sections;
}

/** @deprecated Use {@link getDocsNavigation}. Kept for existing imports. */
export const getDocNavigation = getDocsNavigation;

/** Every doc's slug segments, for `generateStaticParams`. */
export function getAllDocSlugs(): string[][] {
  return source.getPages().map((page) => page.slugs);
}

export async function getDocFromParams(paramsPromise: Promise<{ slug?: string[] }>) {
  const { slug } = await paramsPromise;
  return source.getPage(slug);
}

export interface DocSearchResult {
  title: string;
  content: string;
  url: string;
}

/*
 * Keyword search over the fumadocs search index.
 *
 * Deliberately dependency-free: results feed the AI answer in
 * /api/docs/search, which only needs a handful of relevant passages rather
 * than a ranked full-text engine.
 */
export function searchDocs(query: string, limit = 5): DocSearchResult[] {
  const terms = query
    .toLowerCase()
    .split(/\s+/)
    .filter((term) => term.length > 1);

  if (terms.length === 0) return [];

  const scored = source.getPages().flatMap((page) => {
    const title = page.data.title ?? "";
    const body = page.data.structuredData.contents.map((entry) => entry.content).join("\n");
    const haystack = `${title}\n${page.data.description ?? ""}\n${body}`.toLowerCase();

    // Title hits outrank body hits so the AI prompt leads with the right page.
    const score = terms.reduce((total, term) => {
      if (!haystack.includes(term)) return total;
      return total + (title.toLowerCase().includes(term) ? 3 : 1);
    }, 0);

    return score === 0 ? [] : [{ score, result: { title, content: body, url: page.url } }];
  });

  return scored
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((entry) => entry.result);
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

export interface DocSearchResult {
  title: string;
  content: string;
  url: string;
  section?: string;
}

interface UseDocsSearchOptions {
  /**
   * Debounce delay in milliseconds
   * @default 300
   */
  debounceDelay?: number;
  /**
   * Minimum query length to trigger search
   * @default 2
   */
  minQueryLength?: number;
  /**
   * Maximum number of results to fetch
   * @default 10
   */
  limit?: number;
}

interface UseDocsSearchReturn {
  query: string;
  setQuery: (query: string) => void;
  results: DocSearchResult[];
  isLoading: boolean;
  error: string | null;
  search: (searchQuery?: string) => Promise<void>;
  clearResults: () => void;
  hasSearched: boolean;
}

/**
 * Hook for managing docs search functionality with debouncing and caching
 */
export function useDocsSearch(options: UseDocsSearchOptions = {}): UseDocsSearchReturn {
  const { debounceDelay = 300, minQueryLength = 2, limit = 10 } = options;

  const [query, setQuery] = useState("");
  const [results, setResults] = useState<DocSearchResult[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasSearched, setHasSearched] = useState(false);

  // Cache for search results
  const cacheRef = useRef(new Map<string, DocSearchResult[]>());
  const abortControllerRef = useRef<AbortController | null>(null);
  const debounceTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  /**
   * Perform search API call
   */
  const performSearch = useCallback(
    async (searchQuery: string): Promise<DocSearchResult[]> => {
      // Check cache first
      const cacheKey = `${searchQuery.toLowerCase().trim()}_${limit}`;
      const cached = cacheRef.current.get(cacheKey);
      if (cached) {
        return cached;
      }

      // Cancel previous request
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }

      // Create new abort controller
      abortControllerRef.current = new AbortController();

      try {
        const response = await fetch("/api/docs/search", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify({
            query: searchQuery.trim(),
            limit,
          }),
          signal: abortControllerRef.current.signal,
        });

        if (!response.ok) {
          throw new Error(`Search failed: ${response.statusText}`);
        }

        const data = await response.json();
        const searchResults = data.results ?? [];

        // Cache the results
        cacheRef.current.set(cacheKey, searchResults);

        // Limit cache size to prevent memory issues
        if (cacheRef.current.size > 100) {
          const firstKey = cacheRef.current.keys().next().value;
          if (firstKey) {
            cacheRef.current.delete(firstKey);
          }
        }

        return searchResults;
      } catch (err) {
        if (err instanceof Error && err.name === "AbortError") {
          // Request was cancelled, don't treat as error
          throw err;
        }
        throw new Error(err instanceof Error ? err.message : "Search failed");
      }
    },
    [limit]
  );

  /**
   * Execute search with loading states and error handling
   */
  const search = useCallback(
    async (searchQuery?: string) => {
      const queryToSearch = searchQuery ?? query;

      if (!queryToSearch.trim() || queryToSearch.length < minQueryLength) {
        setResults([]);
        setError(null);
        setHasSearched(false);
        return;
      }

      setIsLoading(true);
      setError(null);

      try {
        const searchResults = await performSearch(queryToSearch);
        setResults(searchResults);
        setHasSearched(true);
      } catch (err) {
        if (err instanceof Error && err.name === "AbortError") {
          // Request was cancelled, don't update state
          return;
        }

        const errorMessage = err instanceof Error ? err.message : "Search failed";
        setError(errorMessage);
        setResults([]);
        setHasSearched(true);
      } finally {
        setIsLoading(false);
      }
    },
    [query, minQueryLength, performSearch]
  );

  /**
   * Clear search results and reset state
   */
  const clearResults = useCallback(() => {
    setQuery("");
    setResults([]);
    setError(null);
    setHasSearched(false);

    // Cancel any pending requests
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    // Clear debounce timeout
    if (debounceTimeoutRef.current) {
      clearTimeout(debounceTimeoutRef.current);
    }
  }, []);

  /**
   * Debounced search effect
   */
  useEffect(() => {
    if (debounceTimeoutRef.current) {
      clearTimeout(debounceTimeoutRef.current);
    }

    if (query.trim() && query.length >= minQueryLength) {
      debounceTimeoutRef.current = setTimeout(() => {
        void search(query);
      }, debounceDelay);
    } else {
      setResults([]);
      setError(null);
      setHasSearched(false);
    }

    return () => {
      if (debounceTimeoutRef.current) {
        clearTimeout(debounceTimeoutRef.current);
      }
    };
  }, [query, minQueryLength, debounceDelay, search]);

  /**
   * Cleanup on unmount
   */
  useEffect(() => {
    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
      if (debounceTimeoutRef.current) {
        clearTimeout(debounceTimeoutRef.current);
      }
    };
  }, []);

  return {
    query,
    setQuery,
    results,
    isLoading,
    error,
    search,
    clearResults,
    hasSearched,
  };
}

import { NextResponse } from "next/server";
import { z } from "zod";
import { searchDocs } from "@/lib/docs";
import { openai } from "@/lib/open-ai";
import { ErrorService } from "@/server/services/error-service";
import { rateLimitService } from "@/server/services/rate-limit-service";

// Sanitize input to prevent prompt injection
function sanitizeForPrompt(text: string): string {
  // Remove potential prompt injection patterns
  return (
    text
      // Remove instruction-like patterns that could manipulate the AI
      .replace(
        /\b(ignore|disregard|forget|override|bypass)\s+(previous|above|all|any)\s+(instructions?|prompts?|rules?)/gi,
        "[REDACTED]"
      )
      // Remove common prompt injection techniques
      .replace(/\b(system|assistant|user)\s*:/gi, "[ROLE]")
      // Remove potential command injections
      .replace(/```[^`]*```/g, "[CODE_BLOCK]")
      // Escape special characters that might be interpreted as markdown or special syntax
      .replace(/[<>]/g, "")
      // Limit consecutive newlines to prevent format manipulation
      .replace(/\n{3,}/g, "\n\n")
      // Trim excessive whitespace
      .trim()
  );
}

const searchRequestSchema = z.object({
  query: z.string().min(1, "Search query is required").max(500, "Search query is too long"),
  limit: z
    .number()
    .optional()
    .default(5)
    .refine((val) => val > 0 && val <= 20, {
      message: "Limit must be between 1 and 20",
    }),
});

export async function POST(req: Request) {
  try {
    // Extract client IP for rate limiting
    // Try to get IP from various headers in order of reliability
    const forwardedFor = req.headers.get("x-forwarded-for");
    const realIp = req.headers.get("x-real-ip");
    const cfConnectingIp = req.headers.get("cf-connecting-ip");

    // Use the first available IP address, with fallback to a generic identifier
    const clientIp = forwardedFor?.split(",")[0]?.trim() ?? realIp ?? cfConnectingIp ?? "anonymous";

    // Apply rate limiting with custom limits for AI search
    // More restrictive than regular search due to OpenAI API costs
    const aiSearchRateLimit = {
      requests: 10, // 10 requests
      duration: 60, // per minute
    };

    try {
      await rateLimitService.checkLimit(clientIp, "ai-docs-search", aiSearchRateLimit);
    } catch (error) {
      // If it's a rate limit error, return appropriate response
      if (ErrorService.isAppError(error) && error.code === "RATE_LIMITED") {
        return NextResponse.json(
          {
            error: "Too many requests",
            message: "You have exceeded the rate limit for AI search. Please try again later.",
            retryAfter: error.metadata?.reset,
          },
          {
            status: 429,
            headers: {
              "X-RateLimit-Limit": String(
                (error.metadata?.limit as number | undefined) ?? aiSearchRateLimit.requests
              ),
              "X-RateLimit-Remaining": String(
                (error.metadata?.remaining as number | undefined) ?? 0
              ),
              "X-RateLimit-Reset": String((error.metadata?.reset as number | undefined) ?? 0),
              "Retry-After": String(
                Math.ceil(((error.metadata?.reset as number) || 0) - Date.now() / 1000)
              ),
            },
          }
        );
      }
      // Re-throw other errors
      throw error;
    }

    // Parse and validate the request body
    const body = await req.json().catch(() => ({}));
    const validationResult = searchRequestSchema.safeParse(body);

    if (!validationResult.success) {
      return NextResponse.json(
        {
          error: "Invalid request",
          details: validationResult.error.issues,
        },
        { status: 400 }
      );
    }

    const { query, limit } = validationResult.data;

    // Get current rate limit status for response headers
    const rateLimitStatus = await rateLimitService.getStatus(clientIp, "ai-docs-search");
    const rateLimitHeaders = {
      "X-RateLimit-Limit": String(rateLimitStatus.limit),
      "X-RateLimit-Remaining": String(rateLimitStatus.remaining),
      "X-RateLimit-Reset": String(rateLimitStatus.reset),
    };

    // Check if client wants JSON response
    const acceptHeader = req.headers.get("accept");
    if (acceptHeader?.includes("application/json")) {
      // Search documentation
      const searchResults = searchDocs(query, limit);
      return NextResponse.json({ results: searchResults }, { headers: rateLimitHeaders });
    }

    // Search documentation for streaming response
    const searchResults = searchDocs(query, limit);

    // If OpenAI isn't configured, fall back to returning JSON results
    if (!openai) {
      return NextResponse.json({ results: searchResults }, { headers: rateLimitHeaders });
    }

    // Generate streaming AI response
    const response = await openai.chat.completions.create({
      model: "gpt-4-turbo-preview",
      messages: [
        {
          role: "system",
          content: `You are a helpful documentation assistant for Shipkit.
          Your responses should be clear, concise, and focused on answering the user's question.
          Include relevant code examples when appropriate.
          Format your responses in markdown.

          Here are some relevant documentation snippets to help you answer:
          ${searchResults.map((result) => `### ${sanitizeForPrompt(result.title)}\n${sanitizeForPrompt(result.content)}`).join("\n\n")}`,
        },
        {
          role: "user",
          content: sanitizeForPrompt(query),
        },
      ],
      temperature: 0.7,
      max_tokens: 500,
      stream: true,
    });

    // Create a text encoder
    const encoder = new TextEncoder();

    // Create a readable stream from the OpenAI response
    const stream = new ReadableStream({
      async start(controller) {
        try {
          for await (const chunk of response) {
            const text = chunk.choices[0]?.delta?.content ?? "";
            if (text) {
              controller.enqueue(encoder.encode(text));
            }
          }
          controller.close();
        } catch (error) {
          controller.error(error);
        }
      },
    });

    // Return the stream with appropriate headers including rate limit info
    const headers = new Headers({
      "Content-Type": "text/plain; charset=utf-8",
      "Cache-Control": "no-cache",
      "Transfer-Encoding": "chunked",
      ...rateLimitHeaders,
    });

    return new Response(stream, { headers });
  } catch (error) {
    // Handle rate limit errors that weren't caught earlier
    if (ErrorService.isAppError(error) && error.code === "RATE_LIMITED") {
      return NextResponse.json(
        {
          error: "Too many requests",
          message: "You have exceeded the rate limit for AI search. Please try again later.",
          retryAfter: error.metadata?.reset,
        },
        {
          status: 429,
          headers: {
            "X-RateLimit-Limit": String((error.metadata?.limit as number | undefined) ?? 10),
            "X-RateLimit-Remaining": String((error.metadata?.remaining as number | undefined) ?? 0),
            "X-RateLimit-Reset": String((error.metadata?.reset as number | undefined) ?? 0),
            "Retry-After": String(
              Math.ceil(((error.metadata?.reset as number) || 0) - Date.now() / 1000)
            ),
          },
        }
      );
    }

    console.error("Search error:", error);
    return NextResponse.json(
      {
        error: "Failed to process search request",
        details: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 }
    );
  }
}
